SET NAMES utf8mb4;

UPDATE Rooms SET Description = 'Phòng 101 là phòng đơn tiêu chuẩn tại tầng 1, diện tích khoảng 22m², thiết kế gọn gàng và tận dụng ánh sáng tự nhiên từ cửa sổ nhìn ra sân vườn. Không gian gồm một giường đơn nệm cao su êm ái, tủ quần áo, bàn làm việc nhỏ và ghế xoay, phù hợp khách công tác cần yên tĩnh để làm việc buổi tối. Phòng tắm riêng có vòi sen, máy sấy tóc, gương trang điểm và bộ đồ vệ sinh cá nhân. Tiện nghi gồm wifi tốc độ cao, điều hòa hai chiều, TV 32 inch, nước uống đóng chai và ấm đun siêu tốc. Hành lang tầng 1 gần sảnh lễ tân nên nhận phòng, trả phòng và gọi hỗ trợ đều thuận tiện. Đây là lựa chọn tiết kiệm, sạch sẽ cho khách đi một mình hoặc lưu trú ngắn ngày.'
WHERE RoomNumber = '101';

UPDATE Rooms SET Description = 'Phòng 102 nằm cuối hành lang tầng 1, ít người qua lại nên rất yên tĩnh vào ban đêm. Diện tích khoảng 22m² với giường đơn, rèm cản sáng, tủ quần áo rộng và kệ để vali. Cửa sổ hướng Đông đón nắng buổi sáng, giúp căn phòng thoáng và dễ chịu. Phòng tắm kính có vòi sen áp lực tốt, khăn tắm thay hằng ngày và đồ dùng cá nhân đầy đủ. Khách được dùng wifi miễn phí, điều hòa, ổ cắm USB sạc nhanh và bàn làm việc. Vị trí gần thang máy và sảnh chính nên thuận tiện cho khách check-in muộn hoặc đi sớm. Phù hợp nhân viên công tác, khách vãng lai hoặc người cần không gian riêng tư với mức giá hợp lý.'
WHERE RoomNumber = '102';

UPDATE Rooms SET Description = 'Phòng 103 là phòng đôi tiêu chuẩn khoảng 28m², bố trí một giường đôi lớn, phù hợp cặp đôi hoặc hai bạn đồng hành. Nội thất tông màu ấm, có smart TV, bàn trà nhỏ, tủ quần áo và gương soi toàn thân. Phòng tắm riêng với bồn rửa, vòi sen, máy sấy và bộ amenities tiêu chuẩn. Cửa sổ nhìn ra lối đi nội bộ, rèm dày giúp ngủ ngon dù khách ra vào sảnh khá nhiều. Tầng 1 gần nhà hàng buổi sáng nên dùng buffet nhanh, không phải chờ thang máy. Wifi, điều hòa, minibar nước suối và ấm pha trà/cà phê đều được trang bị sẵn. Đây là lựa chọn cân bằng giữa giá và sự tiện nghi cho kỳ nghỉ cuối tuần 2 người.'
WHERE RoomNumber = '103';

UPDATE Rooms SET Description = 'Phòng 104 hướng sân trong yên tĩnh, diện tích khoảng 28m², giường đôi nệm êm, lý tưởng cho cặp đôi muốn nghỉ ngơi sau ngày dài. Ban ngày ánh sáng dịu, ban đêm ít tiếng ồn từ đường phố. Trong phòng có bàn trà, hai ghế, smart TV, két an toàn nhỏ và tủ lạnh minibar. Phòng tắm sạch sẽ, có vòi sen, khăn lớn, dép đi trong phòng và đồ vệ sinh. Điều hòa hai chiều, wifi ổn định và ổ cắm hai bên giường giúp sạc điện thoại tiện lợi. Nhân viên dọn phòng hằng ngày, thay khăn theo yêu cầu. Phù hợp nghỉ dưỡng ngắn ngày, khách đi công tác theo cặp hoặc gia đình 2 người không cần view biển.'
WHERE RoomNumber = '104';

UPDATE Rooms SET Description = 'Phòng 201 ở tầng 2, yên tĩnh hơn tầng trệt, có ban công nhỏ nhìn ra hàng cây xanh. Diện tích khoảng 30m² với giường đôi lớn, ga trải chất liệu cotton, hai gối ôm và đèn đọc sách hai bên. Không gian có khu vực ngồi uống trà, smart TV, wifi tốc độ cao và điều hòa. Phòng tắm riêng cửa kính, vòi sen mưa, máy sấy tóc và đồ dùng cá nhân. Ban công đủ chỗ đứng hít thở không khí buổi sáng hoặc uống cà phê. Tầng 2 gần khu thang máy nên di chuyển xuống nhà hàng, hồ bơi và sảnh đều nhanh. Phù hợp cặp đôi muốn phòng yên, có chút không gian ngoài trời mà chưa cần nâng hạng suite.'
WHERE RoomNumber = '201';

UPDATE Rooms SET Description = 'Phòng 202 là Deluxe Suite khoảng 40m², tách biệt khu ngủ và khu tiếp khách. Giường king size, sofa 2 chỗ, bàn trà, tivi 43 inch và minibar. Cửa kính lớn giúp căn phòng sáng, view hướng khuôn viên khách sạn. Phòng tắm rộng có bồn tắm nằm, vòi sen riêng, gương đèn LED và bộ amenities cao cấp. Tủ quần áo walk-in nhỏ, bàn làm việc, két sắt và máy pha cà phê viên nén. Wifi mạnh, điều hòa từng khu, rèm blackout giúp ngủ sâu. Sức chứa tối đa 3 khách, có thể thêm giường phụ cho trẻ em theo yêu cầu. Phù hợp gia đình nhỏ, cặp đôi kỷ niệm hoặc khách muốn không gian rộng hơn phòng tiêu chuẩn.'
WHERE RoomNumber = '202';

UPDATE Rooms SET Description = 'Phòng 203 Deluxe tầng 2, diện tích khoảng 42m², cách ly tiếng ồn tốt nhờ hành lang ít phòng. Khu ngủ giường king, khu khách sofa dài, bàn trà và kệ trang trí. Phòng tắm có bồn ngâm, vòi sen, khăn lớn, áo choàng tắm và dép bông. Tiện nghi gồm smart TV, wifi, điều hòa, minibar, ấm đun, máy sấy và bàn ủi hơi nước. View nhìn ra khoảng xanh, ban ngày thoáng, tối dịu ánh đèn vườn. Nhân viên có thể dọn phòng 2 lần/ngày nếu khách đăng ký. Phù hợp cặp đôi muốn thư giãn, khách lưu trú 3-4 đêm hoặc gia đình 2 người lớn kèm 1 trẻ. Trải nghiệm cao cấp hơn phòng đôi thường, gần mức VIP nhưng giá dễ chịu hơn.'
WHERE RoomNumber = '203';

UPDATE Rooms SET Description = 'Phòng 301 là hạng VIP Ocean View tại tầng 3, diện tích khoảng 55m², cửa kính lớn từ sàn tới trần nhìn ra biển. Ban công rộng kê bàn ghế, thích hợp ngắm bình minh, uống trà chiều hoặc chụp ảnh. Bên trong gồm giường king, sofa bed cho 2 người thêm, sức chứa tối đa 4 khách. Phòng tắm kính trong có bồn jacuzzi, vòi sen mưa, máy sấy, áo choàng và đồ dùng cao cấp. Minibar đầy đủ, máy pha cà phê, smart TV 55 inch, loa bluetooth, két sắt và wifi tốc độ cao. Nội thất gỗ sáng, ánh sáng ấm, rèm tự động hai lớp. Phù hợp gia đình, nhóm bạn hoặc kỳ nghỉ đặc biệt khi muốn view biển và không gian sang trọng.'
WHERE RoomNumber = '301';

UPDATE Rooms SET Description = 'Phòng 302 VIP tầng 3, view biển thoáng đãng cả ngày, diện tích khoảng 52m². Bố trí giường king, khu sinh hoạt với sofa góc, bàn ăn nhỏ 4 chỗ và minibar. Ban công riêng hướng biển, có ghế nằm thư giãn. Phòng tắm lớn với bồn massage, vòi sen riêng, gương trang điểm đèn vàng và bộ amenities nhập. Tiện nghi gồm smart TV, wifi mesh, điều hòa êm, máy pha cà phê, ấm đun, bàn ủi và két an toàn. Ánh sáng tự nhiên rất tốt nhờ kính lớn, đêm có đèn vàng tạo không khí nghỉ dưỡng. Phù hợp cặp đôi kỷ niệm, gia đình 3-4 người hoặc khách muốn kỳ nghỉ cao cấp mà vẫn gần thang máy và quầy lễ tân tầng trệt.'
WHERE RoomNumber = '302';

UPDATE Rooms SET Description = 'Phòng 303 VIP Ocean View là một trong những phòng rộng nhất, khoảng 58m², thiết kế khu ngủ - khu khách - ban công biển tách bạch. Giường lớn, sofa bed, bàn làm việc và hệ thống loa giải trí. Phòng tắm cao cấp có jacuzzi nhìn ra một phần view, vòi sen, máy sấy và đồ dùng xịn. Minibar, máy pha cà phê, smart TV, wifi tốc độ cao, điều hòa và rèm cản sáng đầy đủ. Hiện phòng đang được bảo trì nội thất, thay ga drap, kiểm tra bồn massage và sơn lại tường để đảm bảo tiêu chuẩn VIP khi mở cửa trở lại. Khi sẵn sàng, đây sẽ là lựa chọn hàng đầu cho gia đình hoặc nhóm 4 người muốn view biển, không gian rộng và tiện nghi đầy đủ nhất tại khách sạn.'
WHERE RoomNumber = '303';
